import openpyxl
wb = openpyxl.load_workbook('Bill_Format.xlsx')
ws = wb.active
print('ORIGINAL FILE:')
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, max_col=ws.max_column):
    vals = []
    for cell in row:
        if cell.value is not None:
            vals.append(f'{cell.coordinate}={repr(cell.value)}')
    if vals:
        print(' | '.join(vals))
